const body = $input.first().json.body ?? $input.first().json;
const token = $input.first().json.headers?.['x-webhook-token']
           ?? $input.first().json.headers?.['X-Webhook-Token']
           ?? '';
const expectedToken = $env.WEBHOOK_TOKEN ?? '';
if (expectedToken && token !== expectedToken) throw new Error('Token inválido');

const action = body.action;
const validActions = ['update_event', 'update_status', 'renew_watch'];
if (!action || !validActions.includes(action)) {
  throw new Error('action inválido. Use: ' + validActions.join(', '));
}

if (action !== 'renew_watch' && !body.appointment_id) {
  throw new Error('appointment_id obrigatório para ' + action);
}
if (!body.client_id) throw new Error('client_id obrigatório');

console.log(`[agenda-manager] action=${action} | client=${body.client_id} | appointment=${body.appointment_id ?? 'N/A'}`);

return [{ json: {
  action:         action,
  client_id:      body.client_id,
  appointment_id: body.appointment_id ?? null,
  fields:         body.fields         ?? {},
  status:         body.status         ?? null,
} }];

const apptResult = $input.first().json;
const payload    = $('Validar Payload').first().json;

const appt = Array.isArray(apptResult) ? apptResult[0] : null;
if (!appt) throw new Error(`Agendamento ${payload.appointment_id} não encontrado.`);

const fields = payload.fields ?? {};

// Mescla campos atualizados com dados existentes (fonte de verdade = Banco A)
const merged = {
  service_name:   fields.service_name   ?? appt.service_name,
  customer_name:  fields.customer_name  ?? appt.customer_name,
  customer_phone: fields.customer_phone ?? appt.customer_phone,
  customer_email: fields.customer_email ?? appt.customer_email,
  start_at:       fields.start_at       ?? appt.start_at,
  end_at:         fields.end_at         ?? appt.end_at,
  notes:          fields.notes          ?? appt.notes,
};

return [{ json: {
  appointment_id:     appt.id,
  client_id:          appt.client_id,
  google_event_id:    appt.google_event_id    ?? null,
  google_calendar_id: appt.google_calendar_id ?? null,
  source:             appt.source,
  ...merged,
} }];

const apptResult = $input.first().json;
const payload    = $('Validar Payload').first().json;

const appt = Array.isArray(apptResult) ? apptResult[0] : null;
if (!appt) throw new Error(`Agendamento ${payload.appointment_id} não encontrado.`);

const newStatus = payload.status;
const validStatus = ['pending','confirmed','cancelled','completed','no_show'];
if (!validStatus.includes(newStatus)) {
  throw new Error(`Status inválido: ${newStatus}. Use: ${validStatus.join(', ')}`);
}

if (appt.status === newStatus) {
  console.log(`[agenda-manager] Agendamento já está com status ${newStatus}. Ignorando.`);
  return [];
}

return [{ json: {
  appointment_id:     appt.id,
  client_id:          appt.client_id,
  google_event_id:    appt.google_event_id    ?? null,
  google_calendar_id: appt.google_calendar_id ?? null,
  old_status:         appt.status,
  new_status:         newStatus,
} }];

