const tokens = $input.first().json;
const appt   = $('Preparar Dados para Edição').first().json;

if (!tokens?.found || !appt.google_event_id) {
  console.log(`[agenda-manager] Cliente ${appt.client_id} sem Google Calendar ou evento sem ID. Edição salva apenas no Banco A.`);
  return [];
}

const expiry       = tokens.token_expiry ? new Date(tokens.token_expiry).getTime() : 0;
const needsRefresh = expiry - Date.now() < 5 * 60 * 1000;

return [{ json: {
  ...appt,
  access_token:  tokens.access_token,
  refresh_token: tokens.refresh_token,
  token_expiry:  tokens.token_expiry,
  calendar_id:   tokens.calendar_id ?? appt.google_calendar_id ?? 'primary',
  needs_refresh: needsRefresh,
} }];

const refreshResult = $input.first().json;
const prev = $('Avaliar Tokens (update_event)').first().json;
const newToken  = refreshResult.access_token ?? prev.access_token;
const newExpiry = refreshResult.expires_in
  ? new Date(Date.now() + refreshResult.expires_in * 1000).toISOString()
  : prev.token_expiry;
return [{ json: { ...prev, access_token: newToken, token_expiry: newExpiry } }];

