const tokenData = $('Buscar Tokens (renew_watch)').first().json;
const payload   = $('Validar Payload').first().json;

const row = Array.isArray(tokenData) ? tokenData[0] : null;
if (!row?.client_id) {
  console.log(`[agenda-manager] Cliente ${payload.client_id} sem Google Calendar conectado. Nada a renovar.`);
  return [];
}

if (!row.watch_expiry) {
  return [{ json: { ...row, needs_renewal: true, reason: 'sem watch_expiry registrado' } }];
}

const expiryTs    = new Date(row.watch_expiry).getTime();
const hoursLeft   = (expiryTs - Date.now()) / (1000 * 60 * 60);
const needRenewal = hoursLeft < 24;

console.log(`[agenda-manager] Watch channel expira em ${hoursLeft.toFixed(1)}h. Renovar: ${needRenewal}`);

if (!needRenewal) {
  console.log('[agenda-manager] Watch channel ainda válido. Nada a fazer.');
  return [];
}

return [{ json: {
  ...row,
  needs_renewal: true,
  reason: `expira em ${hoursLeft.toFixed(1)}h`,
} }];

const refreshResult = $input.first().json;
const prev = $('Avaliar Watch Channel').first().json;
const accessToken = refreshResult.access_token ?? prev.access_token;
return [{ json: { ...prev, access_token: accessToken } }];

