const watchResult = $input.first().json;
const prev = $('Avaliar Watch Channel').first().json;

if (!watchResult?.id) {
  console.error('[agenda-manager] Falha ao registrar watch channel:', JSON.stringify(watchResult));
  return [];
}

const newExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

console.log(`[agenda-manager] Novo watch channel: ${watchResult.id} | expira: ${newExpiry}`);

return [{ json: {
  client_id:        prev.client_id,
  new_channel_id:   watchResult.id,
  new_resource_id:  watchResult.resourceId ?? '',
  new_expiry:       newExpiry,
} }];

const action = $('Validar Payload').first().json.action;
console.log(`[agenda-manager] Concluído — action: ${action}`);
return [{ json: { success: true, action } }];
